use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    // Split into build part
    let (s_without_build, build) = match s.split_once('+') {
        Some((main, build_part)) => {
            if build_part.is_empty() {
                return Err(format!("{} is not valid SemVer string", s));
            }
            validate_build_part(build_part)?;
            (main, Some(build_part.to_string()))
        }
        None => (s, None),
    };

    // Split into prerelease part
    let (version_part, prerelease) = match s_without_build.split_once('-') {
        Some((version, pre_part)) => {
            if pre_part.is_empty() {
                return Err(format!("{} is not valid SemVer string", s));
            }
            validate_prerelease_part(pre_part)?;
            (version, Some(pre_part.to_string()))
        }
        None => (s_without_build, None),
    };

    // Parse major.minor.patch
    let parts: Vec<&str> = version_part.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("{} is not valid SemVer string", s));
    }

    let major = parse_number(parts[0], s)?;
    let minor = parse_number(parts[1], s)?;
    let patch = parse_number(parts[2], s)?;

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

fn parse_number(s: &str, original: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err(format!("{} is not valid SemVer string", original));
    }

    // Check for leading zeros (except "0" itself)
    if s.len() > 1 && s.starts_with('0') {
        return Err(format!("{} is not valid SemVer string", original));
    }

    s.parse::<u64>()
        .map_err(|_| format!("{} is not valid SemVer string", original))
}

fn validate_prerelease_part(s: &str) -> Result<(), String> {
    // Prerelease is dot-separated identifiers
    // Each identifier: 0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*
    for ident in s.split('.') {
        if ident.is_empty() {
            return Err("empty prerelease identifier".to_string());
        }
        validate_prerelease_identifier(ident)?;
    }
    Ok(())
}

fn validate_prerelease_identifier(s: &str) -> Result<(), String> {
    // Must only contain [0-9a-zA-Z-]
    for c in s.chars() {
        if !c.is_ascii_alphanumeric() && c != '-' {
            return Err("invalid character in prerelease identifier".to_string());
        }
    }

    // Try to parse as number
    if let Ok(_) = s.parse::<u64>() {
        // It's numeric. Check: must be "0" or [1-9]\d* (no leading zeros)
        if s.len() > 1 && s.starts_with('0') {
            return Err("numeric prerelease identifier has leading zero".to_string());
        }
        return Ok(());
    }

    // Not a pure number. Pattern: \d*[a-zA-Z-][0-9a-zA-Z-]*
    // Must have at least one letter or dash
    if s.chars().any(|c| c.is_ascii_alphabetic() || c == '-') {
        return Ok(());
    }

    Err("invalid prerelease identifier".to_string())
}

fn validate_build_part(s: &str) -> Result<(), String> {
    // Build is dot-separated identifiers
    // Each identifier: [0-9a-zA-Z-]+
    for ident in s.split('.') {
        if ident.is_empty() {
            return Err("empty build identifier".to_string());
        }
        // Must only contain [0-9a-zA-Z-]
        for c in ident.chars() {
            if !c.is_ascii_alphanumeric() && c != '-' {
                return Err("invalid character in build identifier".to_string());
            }
        }
    }
    Ok(())
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut result = format!("{}.{}.{}", v.major, v.minor, v.patch);

    if let Some(ref pre) = v.prerelease {
        result.push('-');
        result.push_str(pre);
    }

    if let Some(ref build) = v.build {
        result.push('+');
        result.push_str(build);
    }

    result
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major.minor.patch first
    match (a.major.cmp(&b.major)) {
        Ordering::Equal => {}
        other => return other,
    }

    match a.minor.cmp(&b.minor) {
        Ordering::Equal => {}
        other => return other,
    }

    match a.patch.cmp(&b.patch) {
        Ordering::Equal => {}
        other => return other,
    }

    // If major.minor.patch are equal, compare prerelease
    // A version without prerelease is GREATER than one with
    nat_cmp(&a.prerelease, &b.prerelease)
}

fn nat_cmp(a: &Option<String>, b: &Option<String>) -> Ordering {
    // Parse the prerelease strings into parts
    let a_parts = match a {
        Some(s) => s.split('.').map(parse_prerelease_part).collect::<Vec<_>>(),
        None => vec![],
    };

    let b_parts = match b {
        Some(s) => s.split('.').map(parse_prerelease_part).collect::<Vec<_>>(),
        None => vec![],
    };

    // Compare parts in order
    for (a_part, b_part) in a_parts.iter().zip(b_parts.iter()) {
        match cmp_prerelease_tag(a_part, b_part) {
            Ordering::Equal => {}
            other => return other,
        }
    }

    // If all parts equal so far, the one with more parts is greater
    // But: a version WITHOUT prerelease (empty parts) is GREATER than one WITH
    match a_parts.len().cmp(&b_parts.len()) {
        Ordering::Equal => Ordering::Equal,
        other => {
            // If both are empty, equal
            if a_parts.is_empty() && b_parts.is_empty() {
                return Ordering::Equal;
            }
            // If one is empty and other isn't, the empty one (no prerelease) is greater
            if a_parts.is_empty() {
                return Ordering::Greater;
            }
            if b_parts.is_empty() {
                return Ordering::Less;
            }
            // Otherwise, more parts is greater
            other
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum PrereleasePart {
    Numeric(u64),
    Alphanumeric(String),
}

fn parse_prerelease_part(s: &str) -> PrereleasePart {
    if let Ok(num) = s.parse::<u64>() {
        PrereleasePart::Numeric(num)
    } else {
        PrereleasePart::Alphanumeric(s.to_string())
    }
}

fn cmp_prerelease_tag(a: &PrereleasePart, b: &PrereleasePart) -> Ordering {
    match (a, b) {
        (PrereleasePart::Numeric(an), PrereleasePart::Numeric(bn)) => an.cmp(bn),
        (PrereleasePart::Numeric(_), PrereleasePart::Alphanumeric(_)) => Ordering::Less,
        (PrereleasePart::Alphanumeric(_), PrereleasePart::Numeric(_)) => Ordering::Greater,
        (PrereleasePart::Alphanumeric(as_), PrereleasePart::Alphanumeric(bs)) => as_.cmp(bs),
    }
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
///
/// Do not guess the prerelease interaction — read `reference/version.py`
/// and check against the oracle. `evaluate.py` compares you to the real
/// `semver` package on every bump of every valid version it generates.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

