    if a.patch != b.patch {
        return if a.patch < b.patch {
            Ordering::Less
        } else {
            Ordering::Greater
        };
    }

    // Handle prerelease comparison
    // Key rule: a version WITHOUT prerelease is GREATER than one WITH prerelease
    match (&a.prerelease, &b.prerelease) {
        (None, None) => Ordering::Equal,
