        (Some(_), None) => Ordering::Less,     // With prerelease < no prerelease
        (Some(a_pre), Some(b_pre)) => {
            // Both have prerelease, compare them lexicographically
            let pre_cmp = compare_prerelease(Some(a_pre.as_str()), Some(b_pre.as_str()));
